import { describe, expect, it } from 'vitest'
import { isCommandResultItemSelectable, isCommandResultItemVisible, isConversationResetCommand, resolveCommandResultSelection } from './slash-command-result'

describe('slash command result helpers', () => {
  it('maps known help quick actions to sendable slash text', () => {
    expect(resolveCommandResultSelection({ id: 'help', title: 'Help', kind: 'quick_action' })).toEqual({
      kind: 'quick_action',
      id: 'help',
      text: '/help',
    })
    expect(resolveCommandResultSelection({ id: 'skill.list', title: 'Skills', kind: 'quick_action' })).toEqual({
      kind: 'quick_action',
      id: 'skill.list',
      text: '/skill list',
    })
  })

  it('allows server-provided slash titles for unknown quick actions', () => {
    expect(resolveCommandResultSelection({ id: 'custom', title: '/custom action', kind: 'quick_action' })).toEqual({
      kind: 'quick_action',
      id: 'custom',
      text: '/custom action',
    })
  })

  it('does not make the current quick action selectable from its own result', () => {
    const item = { id: 'help', title: '/help', kind: 'quick_action' }

    expect(resolveCommandResultSelection(item, 'help')).toBeNull()
    expect(isCommandResultItemSelectable(item, 'help')).toBe(false)
  })

  it('routes an opaque ACP mode id through permission', () => {
    const modeId = ' review:deep '
    expect(resolveCommandResultSelection({ id: modeId, title: modeId, kind: 'runtime_mode' })).toEqual({
      kind: 'runtime_permission',
      modeId,
    })
  })

  it('marks only executable command result rows as selectable', () => {
    expect(isCommandResultItemSelectable({ id: 'skill.list', title: '/skill list', kind: 'quick_action' })).toBe(true)
    expect(isCommandResultItemSelectable({ id: 'skill-a', title: 'skill-a', kind: 'skill' })).toBe(true)
    expect(isCommandResultItemSelectable({ id: 'note', title: 'Note', kind: 'quick_action' })).toBe(false)
    expect(isCommandResultItemSelectable({ id: 'note', title: 'Note' })).toBe(false)
  })

  it('excludes conversation creation and reset controls from command results', () => {
    for (const command of ['new', '/new', '/reset now', ' CLEAR ']) {
      expect(isConversationResetCommand(command)).toBe(true)
      const item = { id: command, title: command, kind: 'quick_action' }
      expect(isCommandResultItemVisible(item)).toBe(false)
      expect(resolveCommandResultSelection(item)).toBeNull()
    }
    expect(isConversationResetCommand('goal clear')).toBe(false)
    expect(isCommandResultItemVisible({ id: 'goal', title: '/goal clear', kind: 'quick_action' })).toBe(true)
  })

})

import type { CommandActionListItem, CommandActionResult } from '@/composables/api/useChat'

export type CommandResultSelection
  = | { kind: 'quick_action', id: string, text: string }
    | { kind: 'runtime_permission', modeId: string }
    | { kind: 'skill', id: string, title: string, description?: string }

export interface PermissionCommandResultCopy {
  modesTitle: string
  modesText: string
  changedTitle: string
  changedText: string
  currentMode: string
}

const QUICK_ACTION_SLASH_TEXT: Record<string, string> = {
  help: '/help',
  'skill.list': '/skill list',
}

export function isConversationResetCommand(command: string): boolean {
  return ['new', 'reset', 'clear'].includes(command.trim().replace(/^\//, '').split(/\s+/)[0]?.toLowerCase() ?? '')
}

function commandResultItemKind(item: CommandActionListItem): string {
  return item.kind?.trim().toLowerCase() ?? ''
}

function commandResultQuickActionID(item: CommandActionListItem): string {
  return item.id?.trim() ?? ''
}

function isCurrentQuickAction(item: CommandActionListItem, currentActionID = ''): boolean {
  const id = commandResultQuickActionID(item)
  return !!id && id === currentActionID.trim()
}

export function resolveCommandResultSelection(
  item: CommandActionListItem,
  currentActionID = '',
): CommandResultSelection | null {
  const kind = commandResultItemKind(item)
  if (kind === 'runtime_mode') {
    const modeId = item.id ?? ''
    return modeId
      ? { kind: 'runtime_permission', modeId }
      : null
  }
  const id = commandResultQuickActionID(item)
  if (kind === 'skill') {
    const title = item.title.trim()
    return id && title
      ? { kind: 'skill', id, title: item.title, description: item.description }
      : null
  }
  if (kind !== 'quick_action' || isCurrentQuickAction(item, currentActionID)) return null
  if (isConversationResetCommand(id) || isConversationResetCommand(item.title)) return null

  const knownText = id ? QUICK_ACTION_SLASH_TEXT[id] : ''
  if (knownText) return { kind: 'quick_action', id, text: knownText }

  const title = item.title.trim()
  return title.startsWith('/')
    ? { kind: 'quick_action', id: id || title, text: title }
    : null
}

export function isCommandResultItemSelectable(item: CommandActionListItem, currentActionID = ''): boolean {
  return resolveCommandResultSelection(item, currentActionID) !== null
}

// The current ACP mode is reported as its own non-selectable row
// (`runtime_mode_current`): the panel must show it so `/permission` answers "which
// mode am I in", but selecting it would be a no-op mode switch.
export function isCommandResultItemDisplayOnly(item: CommandActionListItem): boolean {
  return commandResultItemKind(item) === 'runtime_mode_current'
}

export function isCommandResultItemVisible(item: CommandActionListItem, currentActionID = ''): boolean {
  return isCommandResultItemDisplayOnly(item) || isCommandResultItemSelectable(item, currentActionID)
}

export function commandResultPresentation(
  result: CommandActionResult,
  copy: PermissionCommandResultCopy,
): CommandActionResult {
  if (result.kind !== 'permission_modes' && result.kind !== 'permission_mode_changed') return result
  const changed = result.kind === 'permission_mode_changed'
  return {
    ...result,
    title: changed ? copy.changedTitle : copy.modesTitle,
    text: changed ? copy.changedText : copy.modesText,
    items: (result.items ?? []).map(item => {
      if (item.kind !== 'runtime_mode_current') return item
      const description = item.description?.trim() ?? ''
      return {
        ...item,
        description: description
          ? `${copy.currentMode} · ${description}`
          : copy.currentMode,
      }
    }),
  }
}

