import type { MarkstreamRendererHandle, MarkstreamVirtualMetrics } from 'markstream-vue'
import type { ChatMessage } from '@/store/chat/types'

interface Registration { source: string, final: boolean, renderer: MarkstreamRendererHandle, notify(): void, ready: boolean, settling: boolean }
const renderers = new WeakMap<Element, Registration>()
const complete = (metrics: MarkstreamVirtualMetrics) => metrics.final && metrics.stable && metrics.renderedCount >= metrics.nodeCount

/** markstream 2.0 emits render-final only with virtualScroll enabled. Chat keeps
 * its existing nonvirtual renderer and uses the public metrics/settle handle.
 * No own quiet timer, length guess or virtual-scroll policy is introduced. */
export function bindSpeechRenderer(body: Element, renderer: MarkstreamRendererHandle, source: string, final: boolean, notify: () => void) {
  const previous = renderers.get(body)
  if (previous?.renderer === renderer && previous.source === source && previous.final === final) return
  renderers.set(body, { source, final, renderer, notify, ready: false, settling: false })
}
function ready(body: Element, source: string) {
  const registered = renderers.get(body)
  if (!registered || registered.source !== source || !registered.final || !body.isConnected) return false
  if (registered.ready) return true
  if (complete(registered.renderer.getVirtualMetrics())) { registered.ready = true; registered.notify(); return true }
  if (!registered.settling) {
    registered.settling = true
    // Reuse renderer-owned settlement and cancellation/version checks. Its
    // defaults are not a product latency promise; unstable is never complete.
    void registered.renderer.settle({ flushPendingTimers: true }).then(metrics => {
      registered.settling = false
      if (renderers.get(body) !== registered || !body.isConnected || !complete(metrics)) return
      registered.ready = true; registered.notify()
    }).catch(() => { registered.settling = false })
  }
  return false
}
export function speechRenderComplete(message: ChatMessage, element: Element | null) {
  if (message.role !== 'assistant' || !element?.isConnected) return false
  const bodies = Array.from(element.querySelectorAll('[data-speech-body]'))
  return message.messages.filter(block => block.type === 'text' && block.content).every(block => {
    const body = bodies.find(body => body.getAttribute('data-speech-block-id') === String(block.id))
    return !!body && ready(body, block.type === 'text' ? block.content : '')
  })
}

import { describe, expect, it, vi } from 'vitest'
import { SpeechReplayCache } from './speech-replay-cache'
import { ChatReadAloud, LiveSpeechReplies, speechText } from './chat-read-aloud'
import { normalizeSpeechText } from './speech-rendered-text'
import type { ChatAssistantTurn } from '@/store/chat/types'

const tick = async () => { for (let i = 0; i < 30; i++) await Promise.resolve() }
const reply = (content: string, streaming = true): ChatAssistantTurn => ({ id: 'bubble', turnId: 'turn', runtimeRunId: 'run', role: 'assistant', timestamp: '', streaming, messages: [{ id: 0, type: 'text', content }] })
function bytes(text: string, type = 'audio/wav', identity = 'voice/model/format-one') {
  return { identity, contentType: type, stream: new ReadableStream<Uint8Array>({ start(c) { c.enqueue(new TextEncoder().encode(text)); c.close() } }) }
}
async function consume(stream: ReadableStream<Uint8Array>) { const reader = stream.getReader(); for (;;) { if ((await reader.read()).done) break }; reader.releaseLock() }

describe('uninterrupted text coverage before synthesis', () => {
  it('does not let a settled sibling row consume a distinct live assistant row in the same turn/run', () => {
    const live = new LiveSpeechReplies()
    const old = { ...reply('Old response.', false), id: 'old-row' }
    const fresh = { ...reply('Fresh response. Next'), id: 'fresh-row' }
    expect(live.update([old, fresh], true, false).map(part => part.text)).toEqual(['Fresh response. '])
  })
  it.each([
    '🙂 开头。\n\n请看[文档](https://hidden.test/x)，价格 US$3–6/月；3.14 和版本 1.2.3。\n\n最后一句。',
    '1. 第一项 3.14。\n2. 第二项🙂。\n\n结尾完整。',
    '**重要。**后续也必须朗读。',
    'Dr. Smith has 3.14 dollars. Next sentence is complete.',
  ])('preserves all visible words once in order through per-code-point deltas and final flush: %s', source => {
    const live = new LiveSpeechReplies(), output: string[] = []; let current = ''
    for (const point of Array.from(source)) { current += point; output.push(...live.update([reply(current)], true, false).map(part => part.text)) }
    output.push(...live.update([reply(source, false)], true, false).map(part => part.text))
    expect(normalizeSpeechText(output.join(''))).toBe(normalizeSpeechText(speechText(reply(source, false))))
  })
})

it('keeps full EOF-completed bytes after stop and replays them without a synthesis request', async () => {
  const player = Object.assign(new EventTarget(), { src: '', play: vi.fn(async () => {}), pause: vi.fn(), load: vi.fn() })
  const synthesize = vi.fn(async () => bytes('all generated audio'))
  const sources: Blob[] = [], states: string[] = []
  const speech = new ChatReadAloud({ synthesize, createPlayer: () => player, createURL: source => { sources.push(source as Blob); return 'blob:cached' }, revokeURL: vi.fn(), onState: value => states.push(value.status) })
  const entry = { key: 'turn', cacheKey: 'account/bot/session/run', text: 'Complete response.' }
  speech.enqueue(entry); await tick(); speech.stop()
  expect(speech.replayAvailability(entry)).toBe('ready')
  expect(speech.replay(entry, 'voice/model/format-one')).toBe(true); await tick()
  expect(synthesize).toHaveBeenCalledOnce()
  expect(await sources.at(-1)!.text()).toBe('all generated audio')
  player.dispatchEvent(new Event('playing')); expect(states.at(-1)).toBe('playing'); speech.stop()
  expect(speech.replay({ ...entry, cacheKey: 'other-account/bot/session/run' }, 'voice/model/format-one')).toBe(false)
  expect(speech.replay({ ...entry, text: 'Changed text.' }, 'voice/model/format-one')).toBe(false)
  expect(speech.replay(entry, 'different-voice')).toBe(false)
  expect(synthesize).toHaveBeenCalledOnce()
})

it('retains exact source spans and response order when EOF completion arrives out of order', async () => {
  const cache = new SpeechReplayCache(), abort = new AbortController()
  const first = cache.capture('owner/bot/run', 'First. ', bytes('first audio'), abort.signal)
  const second = cache.capture('owner/bot/run', 'Second.', bytes('second audio'), abort.signal)
  await consume(second.stream)
  expect(cache.status('owner/bot/run', 'First. Second.')).toBe('incomplete')
  await consume(first.stream)
  const parts = cache.read('owner/bot/run', 'First. Second.', 'voice/model/format-one')!
  expect(await Promise.all(parts.map(part => part.text()))).toEqual(['first audio', 'second audio'])
  expect(cache.read('owner/bot/run', 'First. Second.', 'changed-format')).toBeUndefined()
  cache.clear(); expect(cache.status('owner/bot/run', 'First. Second.')).toBe('missing')
})

it('never labels a canceled partial body, missing identity or incomplete message as replayable', async () => {
  const cache = new SpeechReplayCache(), abort = new AbortController()
  const generated = cache.capture('owner/bot/run', 'Generated. ', bytes('complete audio'), abort.signal)
  await consume(generated.stream)
  let feed!: ReadableStreamDefaultController<Uint8Array>
  const unfinished = cache.capture('owner/bot/run', 'Pending.', { identity: 'voice/model/format-one', contentType: 'audio/wav', stream: new ReadableStream({ start(c) { feed = c } }) }, abort.signal)
  const reader = unfinished.stream.getReader(); feed.enqueue(new Uint8Array([1, 2])); await reader.read()
  abort.abort(); await reader.cancel(); reader.releaseLock()
  expect(cache.status('owner/bot/run', 'Generated. Pending.')).toBe('incomplete')
  expect(cache.read('owner/bot/run', 'Generated. Pending.', 'voice/model/format-one')).toBeUndefined()
  const noIdentity = cache.capture('missing', 'Text.', bytes('audio', 'audio/wav', ''), new AbortController().signal)
  await consume(noIdentity.stream); expect(cache.status('missing', 'Text.')).toBe('incomplete')
})
it('includes a final rendered tail arriving after an earlier complete cached prefix', async () => {
  const cache = new SpeechReplayCache(), signal = new AbortController().signal
  await consume(cache.capture('owner/bot/run', 'First.', bytes('first'), signal).stream)
  expect(cache.status('owner/bot/run', 'First.')).toBe('ready')
  await consume(cache.capture('owner/bot/run', ' Final tail.', bytes('tail'), signal).stream)
  expect(cache.status('owner/bot/run', 'First. Final tail.')).toBe('ready')
  expect((await Promise.all(cache.read('owner/bot/run', 'First. Final tail.', 'voice/model/format-one')!.map(part => part.text())))).toEqual(['first', 'tail'])
})

import type { SpeechAudioStream } from './speech-audio-stream'
import { normalizeSpeechText } from './speech-rendered-text'

interface Part { source: string, identity: string, type: string, audio?: Blob }
interface Reply { parts: Part[], version?: string }
export type ReplayAvailability = 'ready' | 'missing' | 'incomplete' | 'changed'

/** Page-memory generated audio only. Stop is separate from unload, as in
 * Howler 2.2.4. No new synthesis, persistent history write, TTL or quota policy.
 * Keys are supplied by the owner (account/Bot/session/run); auth changes clear
 * this page memory. Server identity is revalidated before a cached replay. */
export class SpeechReplayCache {
  private replies = new Map<string, Reply>()
  private changed: () => void
  constructor(changed: () => void = () => {}) { this.changed = changed }
  clear() { this.replies.clear(); this.changed() }
  capture(key: string, source: string | (() => string), audio: SpeechAudioStream, signal: AbortSignal): SpeechAudioStream {
    const reply = this.replies.get(key) ?? { parts: [] }
    this.replies.set(key, reply)
    const sourceText = () => typeof source === 'function' ? source() : source
    const part: Part = { source: sourceText(), identity: audio.identity ?? '', type: audio.contentType }
    // Final source can precede the renderer's final visible tail. A new audio
    // part is a new completed version, not a mutation of the old cached bytes.
    reply.version = undefined
    reply.parts.push(part); this.changed()
    const reader = audio.stream.getReader(), chunks: ArrayBuffer[] = []
    let canceled = false
    // Tap the consumed stream instead of teeing into a faster unbounded branch.
    const stream = new ReadableStream<Uint8Array>({
      pull: async output => {
        try {
          const next = await reader.read()
          if (next.done) {
            part.source = sourceText()
            if (!canceled && !signal.aborted && chunks.length && part.identity) part.audio = new Blob(chunks, { type: part.type })
            reader.releaseLock(); this.changed(); output.close(); return
          }
          chunks.push(new Uint8Array(next.value).buffer)
          output.enqueue(next.value)
        } catch (error) { this.changed(); reader.releaseLock(); output.error(error) }
      },
      cancel: reason => { canceled = true; this.changed(); void reader.cancel(reason).catch(() => {}); reader.releaseLock() },
    }, { highWaterMark: 0 })
    return { ...audio, stream }
  }
  status(key: string, text: string): ReplayAvailability {
    const reply = this.replies.get(key)
    if (!reply) return 'missing'
    if (!reply.parts.length || reply.parts.some(part => !part.audio || !part.identity)) return 'incomplete'
    if (new Set(reply.parts.map(part => part.identity)).size !== 1 || new Set(reply.parts.map(part => part.type)).size !== 1) return 'changed'
    const version = normalizeSpeechText(text)
    if (normalizeSpeechText(reply.parts.map(part => part.source).join('')) !== version || (reply.version !== undefined && reply.version !== version)) return 'changed'
    reply.version ??= version
    return 'ready'
  }
  read(key: string, text: string, identity: string): Blob[] | undefined {
    if (this.status(key, text) !== 'ready') return
    const parts = this.replies.get(key)!.parts
    if (!identity || parts.some(part => part.identity !== identity)) return
    return parts.map(part => part.audio!)
  }
}

import { describe, expect, it } from 'vitest'
import { LiveSpeechReplies } from './chat-read-aloud'
import type { ChatAssistantTurn } from '@/store/chat/types'

const message = (content: string, streaming = true): ChatAssistantTurn => ({ id: 'bubble', turnId: 'turn', runtimeRunId: 'run', role: 'assistant', timestamp: '', streaming, messages: [{ id: 0, type: 'text', content }] })
describe('prosody boundaries across incremental tokens', () => {
  it.each(['Dr.', 'Mr.', 'Prof.', 'U.S.', 'Ph.D.', '3.', '1.', '第3.'])('does not commit an ambiguous partial prefix %s as its own synthesis request', prefix => {
    const live = new LiveSpeechReplies()
    expect(live.update([message(prefix)], true, false)).toEqual([])
  })
  it('keeps a title and following name together instead of resetting context after Dr.', () => {
    const live = new LiveSpeechReplies()
    expect(live.update([message('Dr.')], true, false)).toEqual([])
    expect(live.update([message('Dr. Smith has 3.14 dollars. Next')], true, false)).toEqual([{ key: 'turn', messageId: 'bubble', text: 'Dr. Smith has 3.14 dollars. ' }])
  })
  it('keeps decimal/version digits and ordered-list labels with their content', () => {
    for (const text of ['The value is 3.14 and version 1.2.3 is ready', '1. First item', '2. Second item', 'U.S. policy and Ph.D. students']) {
      expect(new LiveSpeechReplies().update([message(text)], true, false)).toEqual([])
    }
  })
  it('does not break mixed-language clauses at an abbreviation or comma, but can commit a clear CJK sentence', () => {
    const live = new LiveSpeechReplies()
    expect(live.update([message('请看第3.14项，Dr. Smith 说明')], true, false)).toEqual([])
    expect(live.update([message('请看第3.14项，Dr. Smith 说明。下一句')], true, false)).toEqual([{ key: 'turn', messageId: 'bubble', text: '请看第3.14项，Dr. Smith 说明。' }])
  })
  it('retains a trailing English period for textual lookahead; finalization flushes a genuine single sentence', () => {
    const live = new LiveSpeechReplies()
    expect(live.update([message('A complete sentence.')], true, false)).toEqual([])
    expect(live.update([message('A complete sentence.', false)], true, false)).toEqual([{ key: 'turn', messageId: 'bubble', text: 'A complete sentence.' }])
  })
})

/** Conservative streaming boundaries, using native sentence segmentation plus
 * the abbreviation/initial/decimal protection used by LiveKit's basic sentence
 * tokenizer. Pipecat's SimpleTextAggregator likewise retains ambiguous periods
 * for textual lookahead rather than committing punctuation on the token alone.
 * Sources and deliberately excluded length/delay heuristics: continuity DESIGN. */
export function completedSpeechPrefix(text: string): number {
  const protect = (value: string) => value.replace(/\./gu, '\u2060')
  const masked = text
    .replace(/\b(?:Mr|Mrs|Ms|Dr|St|Prof|Capt|Cpt|Lt|Inc|Ltd|Jr|Sr|Co|Ph\.D)\./gu, protect)
    .replace(/\b(?:[A-Za-z]\.){2,}/gu, protect)
    .replace(/\b[A-Z]\.(?=\s+[A-Z][\p{L}])/gu, protect)
    .replace(/[\p{L}\p{N}]\.(?=[\p{L}\p{N}])/gu, protect)
    .replace(/(?:^|\s)\d+\.(?=\s|$)/gu, protect)
    .replace(/\.{2,}/gu, protect)
  // Masks have exactly the same UTF-16 length, so offsets still name the
  // untouched visible text. No synthetic overlap is sent to TTS or read twice.
  const sentences = typeof Intl.Segmenter === 'function'
    ? Array.from(new Intl.Segmenter(undefined, { granularity: 'sentence' }).segment(masked), item => item.segment)
    : masked.match(/[^。！？.!?\n]*[。！？.!?\n]+(?:["'”’」』)）]*\s*)?|.+$/gu) ?? []
  let end = 0
  for (const sentence of sentences) {
    if (!/[\p{Sentence_Terminal}\n]["'”’」』)）]*\s*$/u.test(sentence)) break
    const next = end + sentence.length
    // As in Pipecat, punctuation alone is not enough: a following token or
    // response end resolves decimals, initials and Markdown closing delimiters.
    // The latter can still change how the renderer projects a CJK sentence.
    if (!masked.slice(next).trim()) break
    end = next
  }
  return end
}

import { expect, it } from 'vitest'
import type { ChatAssistantTurn } from '@/store/chat/types'
import { LiveSpeechReplies } from './chat-read-aloud'
import { SpeechReplayCache } from './speech-replay-cache'

const message = (text: string, streaming: boolean, run?: string): ChatAssistantTurn => ({ id: 'same-render-row', turnId: 'original-turn', ...(run ? { runtimeRunId: run } : {}), role: 'assistant', streaming, timestamp: '', messages: [{ id: 0, type: 'text', content: text }] })
const visible = (m: ChatAssistantTurn) => m.messages.flatMap(block => block.type === 'text' ? [block.content] : []).join('')
const collect = (live: LiveSpeechReplies, m: ChatAssistantTurn) => live.update([m], true, false, false, item => visible(item as ChatAssistantTurn)).map(part => part.text)
function started() {
  const live = new LiveSpeechReplies()
  expect(collect(live, message('Original sentence. Waiting', true, 'original-run'))).toEqual(['Original sentence. '])
  return live
}
it.each([['retained', 'original-run'], ['omitted', undefined]])('commits a delayed final tail exactly once when runtimeRunId is %s', (_name, run) => {
  const live = started(), final = message('Original sentence. Delayed tail.', false, run)
  expect(collect(live, final)).toEqual(['Delayed tail.'])
  expect(collect(live, final)).toEqual([])
  expect(collect(live, final)).toEqual([])
})
it('keeps actual EOF-completed cache coverage ready after repeated final DOM collection without a runtime run id', async () => {
  const live = new LiveSpeechReplies(), cache = new SpeechReplayCache(), signal = new AbortController().signal
  const rows = [message('Original sentence. Waiting', true, 'original-run'), message('Original sentence. Delayed tail.', false), message('Original sentence. Delayed tail.', false)]
  let count = 0
  for (const row of rows) for (const text of collect(live, row)) {
    count++
    const audio = cache.capture('account/bot/scope/original-run/same-render-row', text, { identity: 'same-effective-voice-model-format', contentType: 'audio/wav', stream: new ReadableStream({ start(c) { c.enqueue(new Uint8Array([count])); c.close() } }) }, signal)
    const reader = audio.stream.getReader(); while (!(await reader.read()).done) {}; reader.releaseLock()
  }
  expect(cache.status('account/bot/scope/original-run/same-render-row', 'Original sentence. Delayed tail.')).toBe('ready')
  expect(count).toBe(2)
})
it('keeps an explicitly identified new run on its own cursor after an omitted-run final tail', () => {
  const live = started()
  expect(collect(live, message('Original sentence. Delayed tail.', false))).toEqual(['Delayed tail.'])
  expect(collect(live, message('New sentence. Waiting', true, 'new-run'))).toEqual(['New sentence. '])
  expect(collect(live, message('New sentence. New tail.', false))).toEqual(['New tail.'])
  expect(collect(live, message('New sentence. New tail.', false))).toEqual([])
})
it('retains interruption fences and establishes a silent history baseline after scope reset', () => {
  const live = started()
  live.interrupt([message('Original sentence. Waiting', true, 'original-run')])
  expect(collect(live, message('Original sentence. Delayed tail.', false))).toEqual([])
  expect(collect(live, message('Original sentence. Late frame.', true, 'original-run'))).toEqual([])
  expect(collect(live, message('New sentence. Waiting', true, 'new-run'))).toEqual(['New sentence. '])
  live.reset()
  expect(collect(live, message('History in next scope.', false))).toEqual([])
  expect(collect(live, message('Fresh scope sentence. Waiting', true, 'scope-run'))).toEqual(['Fresh scope sentence. '])
})

// @vitest-environment jsdom
import { afterEach, expect, it, vi } from 'vitest'
import { ChatReadAloud } from './chat-read-aloud'
import { beginSpeechTiming } from './speech-timing'

interface TraceRow { events: { event: string }[] }
const traces = () => (window as unknown as { __memohSpeechTiming: { snapshot(): TraceRow[], clear(): void } }).__memohSpeechTiming
const settle = async () => { for (let i = 0; i < 20; i++) await Promise.resolve() }
afterEach(() => {
  sessionStorage.removeItem('memoh.speechTiming')
  traces()?.clear()
})

it('timing opt-in preserves cancellation of a late response without creating or replaying audio', async () => {
  sessionStorage.setItem('memoh.speechTiming', '1')
  const timing = beginSpeechTiming('manual')!
  let resolve!: (value: { stream: ReadableStream<Uint8Array>, contentType: string }) => void
  let signal: AbortSignal | undefined
  const synthesize = vi.fn((_text: string, requestSignal: AbortSignal) => {
    signal = requestSignal
    return new Promise<{ stream: ReadableStream<Uint8Array>, contentType: string }>(done => { resolve = done })
  })
  const createPlayer = vi.fn(() => { throw new Error('late response must not create a player') })
  const createURL = vi.fn(() => { throw new Error('late response must not create a URL') })
  const cancel = vi.fn()
  const controller = new ChatReadAloud({ synthesize, createPlayer, createURL, revokeURL: vi.fn(), onState: vi.fn() })
  controller.enqueue({ key: 'private-turn-id', text: 'private spoken text', timing })
  await settle()
  controller.stop()
  expect(signal?.aborted).toBe(true)
  resolve({ stream: new ReadableStream<Uint8Array>({ cancel }), contentType: 'audio/mpeg' })
  await settle()
  expect(cancel).toHaveBeenCalledOnce()
  expect(synthesize).toHaveBeenCalledOnce()
  expect(createPlayer).not.toHaveBeenCalled()
  expect(createURL).not.toHaveBeenCalled()
  const snapshot = traces().snapshot()
  expect(snapshot.some(row => row.events.some(event => event.event === 'interrupted'))).toBe(true)
  expect(JSON.stringify(snapshot)).not.toMatch(/private-turn-id|private spoken text/u)
})

it('timing opt-in keeps blocked playback on the same loaded source and never restarts a stopped queue', async () => {
  sessionStorage.setItem('memoh.speechTiming', '1')
  const target = new EventTarget()
  const player = Object.assign(target, {
    src: '', pause: vi.fn(), load: vi.fn(),
    play: vi.fn<() => Promise<void>>()
      .mockRejectedValueOnce(Object.assign(new Error('private autoplay error'), { name: 'NotAllowedError' }))
      .mockResolvedValue(undefined),
  })
  const synthesize = vi.fn(async () => new Blob(['controlled local bytes']))
  const changed = vi.fn()
  const controller = new ChatReadAloud({ synthesize, createPlayer: () => player, createURL: () => 'blob:private-fixture', revokeURL: vi.fn(), onState: changed })
  controller.enqueue({ key: 'private-turn-id', text: 'private spoken text', timing: beginSpeechTiming('manual') })
  await settle()
  expect(changed).toHaveBeenLastCalledWith(expect.objectContaining({ status: 'blocked' }))
  const sameSource = player.src
  controller.resume()
  expect(player.play).toHaveBeenCalledTimes(2)
  expect(synthesize).toHaveBeenCalledOnce()
  expect(player.src).toBe(sameSource)
  player.dispatchEvent(new Event('playing'))
  expect(changed).toHaveBeenLastCalledWith(expect.objectContaining({ status: 'playing' }))
  controller.stop()
  player.dispatchEvent(new Event('playing'))
  player.dispatchEvent(new Event('ended'))
  await settle()
  expect(changed).toHaveBeenLastCalledWith(expect.objectContaining({ status: 'idle' }))
  expect(synthesize).toHaveBeenCalledOnce()
  expect(JSON.stringify(traces().snapshot())).not.toMatch(/private-turn-id|private spoken text|private autoplay error|blob:private-fixture/u)
})

